import React from "react";
import { ShoppingBag, Menu } from "lucide-react";
import JewelArt from "./JewelArt";
import { COLORS, FONT_DISPLAY } from "../constants/theme";

export default function Nav({
  scrolled,
  menuOpen,
  setMenuOpen,
  cartOpen,
  setCartOpen,
  cartCount,
  bump,
  scrollTo,
  setFilter,
}) {
  return (
    <header
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        zIndex: 50,
        background: scrolled ? COLORS.boneSoft : "transparent",
        borderBottom: scrolled ? `1px solid ${COLORS.line}` : "1px solid transparent",
        transition: "background 0.3s ease, border-color 0.3s ease",
      }}
    >
      <div style={{ maxWidth: 1240, margin: "0 auto" }} className="flex items-center justify-between px-6 md:px-10">
        <a
          href="#top"
          style={{
            fontFamily: FONT_DISPLAY,
            fontSize: 22,
            letterSpacing: "0.04em",
            color: scrolled ? COLORS.ink : COLORS.bone,
            display: "flex",
            alignItems: "center",
            gap: 8,
            padding: "18px 0",
          }}
        >
          <JewelArt type="ring" style={{ width: 22, height: 22 }} />
          Nyasa
        </a>

        <nav className="hidden md:flex items-center" style={{ gap: 32 }}>
          {["Rings", "Necklaces", "Earrings"].map((c) => (
            <button
              key={c}
              onClick={() => scrollTo("shop")}
              className="underline-grow"
              style={{
                background: "none",
                border: "none",
                fontSize: 14,
                letterSpacing: "0.03em",
                color: scrolled ? COLORS.ink : COLORS.bone,
              }}
            >
              {c}
            </button>
          ))}
          <button
            onClick={() => scrollTo("craft")}
            className="underline-grow"
            style={{ background: "none", border: "none", fontSize: 14, letterSpacing: "0.03em", color: scrolled ? COLORS.ink : COLORS.bone }}
          >
            The Craft
          </button>
          <button
            onClick={() => scrollTo("faq")}
            className="underline-grow"
            style={{ background: "none", border: "none", fontSize: 14, letterSpacing: "0.03em", color: scrolled ? COLORS.ink : COLORS.bone }}
          >
            FAQ
          </button>
        </nav>

        <div className="flex items-center" style={{ gap: 14 }}>
          <button
            onClick={() => setCartOpen(true)}
            aria-label="Open cart"
            style={{
              background: "none",
              border: "none",
              position: "relative",
              color: scrolled ? COLORS.ink : COLORS.bone,
              padding: 8,
            }}
          >
            <ShoppingBag size={20} strokeWidth={1.6} />
            {cartCount > 0 && (
              <span
                className={bump ? "cart-badge-bump" : ""}
                style={{
                  position: "absolute",
                  top: 2,
                  right: 2,
                  background: COLORS.rust,
                  color: COLORS.bone,
                  fontSize: 10,
                  width: 16,
                  height: 16,
                  borderRadius: "50%",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                {cartCount}
              </span>
            )}
          </button>
          <button
            className="md:hidden"
            onClick={() => setMenuOpen((v) => !v)}
            aria-label="Toggle menu"
            style={{ background: "none", border: "none", color: scrolled ? COLORS.ink : COLORS.bone, padding: 8 }}
          >
            <Menu size={22} strokeWidth={1.6} />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div
          className="md:hidden"
          style={{ background: COLORS.boneSoft, borderTop: `1px solid ${COLORS.line}`, padding: "10px 24px 20px" }}
        >
          {["Rings", "Necklaces", "Earrings"].map((c) => (
            <button
              key={c}
              onClick={() => scrollTo("shop")}
              style={{ display: "block", padding: "12px 0", background: "none", border: "none", fontSize: 16 }}
            >
              {c}
            </button>
          ))}
          <button onClick={() => scrollTo("craft")} style={{ display: "block", padding: "12px 0", background: "none", border: "none", fontSize: 16 }}>
            The Craft
          </button>
          <button onClick={() => scrollTo("faq")} style={{ display: "block", padding: "12px 0", background: "none", border: "none", fontSize: 16 }}>
            FAQ
          </button>
        </div>
      )}
    </header>
  );
}
